// Delegate clicks because chapter pages are rendered dynamically.
document.addEventListener('click',event=>{const image=event.target.closest('#app .source-figure img');if(!image)return;const caption=image.closest('figure')?.querySelector('figcaption')?.textContent||image.alt||'';if(window.Fancybox){Fancybox.show([{src:image.currentSrc||image.src,caption}],{Images:{zoom:true}});return}const dialog=document.getElementById('image-viewer-fallback');dialog.querySelector('img').src=image.currentSrc||image.src;dialog.querySelector('img').alt=image.alt;dialog.querySelector('figcaption').textContent=caption;dialog.showModal()});
document.addEventListener('DOMContentLoaded',()=>{const dialog=document.getElementById('image-viewer-fallback');dialog.querySelector('button').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()})});
